entries[431887] = { ["name"] = "Sengende Schreie", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie schreiende Seele entfesselt glühende Schreie, was allen Spielercharakteren alle 3 Sek. 36262 Schattenflammenschaden zufügt und den verursachten Schattenflammenschaden des Effekts um 100% erhöht. Dieser Effekt ist stapelbar.\n\n' Geister der Kaldorei ' in der Nähe verzweifeln und werden selbst zu schreienden Seelen." }
