entries[432021] = { ["name"] = "Fläschchen des alchemistischen Chaos", ["text"] = "Sofort\nTrinkt dies, um einen zufälligen Sekundärwert um 158 zu erhöhen, wobei allerdings zwei anderer Sekundärwerte um 13 verringert werden. Diese Effekte werden alle 30 Sek. zufällig verändert.\n\nHält 1 Stunde lang und über den Tod hinaus an. Die Benutzung eines identischen Fläschchens verlängert die Dauer um 1 Stunde" }
