entries[432027] = { ["name"] = "Giftblitz", ["text"] = "30 Meter Reichweite\nWirken in 2 sek.\nDer Zaubernde schleudert einen mächtigen Giftklumpen auf sein aktuelles Ziel, fügt diesem Naturschaden zu und vergiftet es, sodass es 5 Sek. lang alle 1 Sek. zusätzlichen Naturschaden erleidet." }
