entries[432035] = { ["name"] = "Schlitzende Bedrohung", ["text"] = "Nahkampfreichweite\nSofort\nDer Zaubernde entfesselt 2 Sek. lang einen Wirbel aus Angriffen, fügt seinem Ziel alle 5.2 Sek. 1 körperlichen Schaden zu und lässt es 6 Sek. lang alle 1.5 Sek. für 1 körperlichen Schaden bluten. Dieser Effekt ist stapelbar." }
