entries[432072] = { ["name"] = "Feuersturm", ["text"] = "Unbegrenzte Reichweite\nSofort\nFyrakk lässt brennende Meteore auf Spielercharaktere herabregnen, fügt Spielercharakteren innerhalb von 9 Metern um die Einschlagsorte 362618 Schattenflammenschaden zu und erschafft bei Einschlag ' Tobende Flammen ' .\n\nDie Splitter der Meteore treffen auch Amirdrassil und fügen Spielercharakteren innerhalb von 4 Metern um die Einschlagsorte 725237 Schattenflammenschaden zu." }
