entries[432105] = { ["name"] = "Erschaffen", ["text"] = "100 Meter Reichweite\nSofort\nDie Seelen von Gegnern, die Schaden durch Euren Oberanführer erleiden, werden gespalten und erleiden 15 Sek. lang um 5 % erhöhten Schaden durch Euch und Eure Begleiter." }
