entries[432124] = { ["name"] = "Toxische Absonderung", ["text"] = "Sofort\nDer Zaubernde verströmt Gift aus seinem Körper, wodurch seine Treffer 5 Sek. lang alle 1 Sek. Naturschaden verursachen und die Bewegungsgeschwindigkeit um 7% verringern.\n\nDieser Effekt ist stapelbar.\n(3s Abklingzeit)" }
entries[432125] = { ["name"] = "Giftbiss", ["text"] = "Nahkampfreichweite\nWirken in 2 sek.\nDer Zaubernde beißt sein aktuelles Ziel, um Gift zu injizieren, was 7 Naturschaden und 5 Sek. lang alle 1 Sek. 1 Naturschaden verursacht." }
entries[432126] = { ["name"] = "10.2.5 HSAnn - HS Minion - Transform - Baron Geddon" }
entries[432127] = { ["name"] = "Vergifteter Panzer", ["text"] = "Nahkampfreichweite\nWirken in 2 sek.\nDer Zaubernde bildet Schichten eines Chitinpanzers, der 5 Sek. lang bestehen bleibt und mit mächtigem Gift überzogen ist, was den erlittenen Schaden verringert und Gift auf Angreifer zurückspritzt, sodass diese regelmäßigen Naturschaden erleiden.\n(2s Abklingzeit)" }
entries[432128] = { ["name"] = "10.2.5 HSAnn - HS Spell - Buff - Blessing of Kings" }
entries[432130] = { ["name"] = "Hervorbrechende Gespinste", ["text"] = "Wirken in 3 sek.\nKi'katal die Ernterin löst mehrere Ausbrüche von Spinnennetzen aus, die 8000683 Naturschaden verursachen und getroffene Spielercharaktere für 3 Sek. betäuben." }
entries[432131] = { ["name"] = "Kerzenerhelltes Bollwerk", ["text"] = "100 Meter Reichweite\nSofort\nVerringert sämtlichen erlittenen Schaden um 80%." }
entries[432132] = { ["name"] = "Hervorbrechende Gespinste", ["text"] = "300 Meter Reichweite\nSofort\nKi'katal die Ernterin löst mehrere Ausbrüche von Spinnennetzen aus, die 8000683 Naturschaden verursachen und getroffene Spielercharaktere für 3 Sek. betäuben." }
entries[432133] = { ["name"] = "Kerzenerhelltes Bollwerk", ["text"] = "Wirken in 1.5 sek.\nVerringert den von Verbündeten in der Nähe erlittenen Schaden 8 Sek. lang um 80%." }
entries[432135] = { ["name"] = "Bonk!", ["text"] = "Nahkampfreichweite\nWirken in 2 sek.\nFügt dem Spielercharakter 10 körperlichen Schaden zu." }
entries[432136] = { ["name"] = "Eingesponnener Hieb", ["text"] = "Nahkampfreichweite\nWirken in 1.5 sek.\nDer Zaubernde schlägt auf sein aktuelles Ziel mit einer umwobenen Klaue ein, bereitet sich dabei auf einen Folgeangriff vor, fügt dem Ziel Naturschaden zu, verringert dessen Bewegungsgeschwindigkeit 5 Sek. lang um 35 und sofort fügt ihm sofort danach körperlichen Schaden zu." }
entries[432141] = { ["name"] = "Eisiger Schlitzer", ["text"] = "Nahkampfreichweite\nWirken in 1.5 sek.\nDer Zaubernde startet eine Kombo gegen sein aktuelles Ziel und schwingt dabei eine pheromongekühlte Waffe, die Frostschaden verursacht und zusätzlich 5 Sek. lang um 30 verlangsamt. Er folgt dem mit einem Klauenangriff, der zusätzlichen körperlichen Schaden verursacht." }
entries[432142] = { ["name"] = "Giftschlitzer", ["text"] = "Nahkampfreichweite\nWirken in 1.5 sek.\nDer Zaubernde startet eine Kombo gegen sein aktuelles Ziel und schwingt dabei eine giftbeschichtete Waffe, die Naturschaden und zusätzlich 3 Sek. lang alle 1 Sek. weiteren Naturschaden verursacht. Er folgt dem mit einem Klauenangriff, der zusätzlichen körperlichen Schaden verursacht." }
entries[432150] = { ["name"] = "Blendender Sand", ["text"] = "Wirken in 3 sek.\nWirft eine Handvoll Sand, die alle Gegner in einem kegelförmigen Bereich vor dem Zaubernden für 4 Sek. desorientiert." }
entries[432151] = { ["name"] = "Frostblitz", ["text"] = "40 Meter Reichweite\nWirken in 2 sek.\nDer Zaubernde verschießt einen Eisblitz auf sein aktuelles Ziel, der diesem Frostschaden zufügt und es 3 Sek. lang um 30 verlangsamt." }
