entries[432455] = { ["name"] = "Edler fliegender Teppich", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen edlen fliegenden Teppich oder gibt ihn wieder frei. Dieses Fortbewegungsmittel passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n\"Magier haben beim Feiern auf dem Nobelgartenfest die gewöhnliche Festdekoration in ein schwebendes Spektakel verwandelt, doch ein verärgerter Druide hat sie gestohlen.\"\nBeute von:\nDaetan Flinkfeder\nFesttag:\nNobelgartenfest" }
