entries[432463] = { ["name"] = "Hammerfall", ["text"] = "Schutz\n'Schild der Rechtschaffenen' und 'Wort der Herrlichkeit' rufen einen Himmelshammer auf einen Gegner in der Nähe herab.\n\nWährend 'Himmelsbeben' aktiv ist, ruft dieser Effekt einen zusätzlichen Himmelshammer herab.\n\nVergeltung\nrufen einen Himmelshammer auf einen Gegner in der Nähe herab.\n\nWährend 'Himmelsbeben' aktiv ist, ruft dieser Effekt einen zusätzlichen Himmelshammer herab.\n\n(100ms Abklingzeit)" }
