entries[432472] = { ["name"] = "Heilige Waffe", ["text"] = "40 Meter Reichweite\nSofort 1 min Wiederaufladung\n2 Aufladungen\nZwingt das Licht, sich zu konzentrieren und als 'Heilige Bewaffnung' zu manifestieren, die von Eurem Ziel geführt werden kann.\n\nHeilige Waffe :\n\nWährend Ihr eine 'Heilige Waffe' führt, haben Eure Zauber und Fähigkeiten eine Chance, Zielen in der Nähe (104% der Angriffskraft) zusätzlichen Heiligschaden zuzufügen oder sie um diesen Wert zusätzlich zu heilen. Der Effekt wird gesteigert, wenn die heilige Waffe ein Einzelziel trifft, und wird über 5 Ziele abgeschwächt. Hält 20 Sek. lang an.\n\nWird nach dem Einsatz zu 'Heiliges Bollwerk'." }
entries[432473] = { ["name"] = "Fläschchen rettender Barmherzigkeit", ["text"] = "Sofort\nDirekte Heilung eines verbündeten Spielercharakters unter 20% Gesundheit erhöht die hervorgerufene Heilung 10 Sek. lang um 5 bis 10% (basierend auf der Herstellungsqualität).\n\nHält 1 Stunde lang und über den Tod hinaus an. Die Benutzung eines identischen Fläschchens verlängert die Dauer um 1 Stunde" }
