entries[432626] = { ["name"] = "Unangefochtene Dominanz", ["text"] = "Vergeltung\nEuer Zauber 'Hammer des Lichts' belegt Ziele mit 'Richturteil' und erhöht Euer Tempo für 6 Sek. um 15%.\n\nSchutz\nEuer Zauber 'Hammer des Lichts' gewährt 'Schild der Rechtschaffenen', ruft unter dem Ziel eine 'Weihe' hervor und erhöht Euer Tempo für 6 Sek. um 12%.\n\nZusätzlich gewährt 'Auge von Tyr' 3 Heilige Kraft.\n\n(1s Abklingzeit)" }
