entries[432692] = { ["name"] = "Schlagendes Herz des Wassers", ["text"] = "Tränkt Euch im Kampf regelmäßig mit besudeltem ursprünglichen Quellwasser, das für 15 Sek. Eure Vielseitigkeit um 23 sowie Eure Bewegungsgeschwindigkeit um 10% verringert.\nWenn Ihr die Unreinheiten des Wassers bannt, kehrt sich der Effekt um und erhöht für 15 Sek. Eure Vielseitigkeit um 96 , Eure Bewegungsgeschwindigkeit um 10% und gewährt allen Verbündeten in der Nähe einen Schild in Höhe von 587 ." }
entries[432699] = { ["name"] = "Umbrelskuls gebrochenes Herz", ["text"] = "100 Meter Reichweite\nCa. 1.5 Procs pro Minute\nEure schädlichen Zauber und Fähigkeiten haben eine geringe Chance, die tragischen Arkanmächte anzurufen, damit sie Euer Ziel mit 'Kristallkrankheit' belegen. Betroffene Ziele erleiden [Quellwert] Arkanschaden im Verlauf von 10 Sek., der mit jeder Sekunde ansteigt.\n\nWenn die Gesundheit von Kreaturen (ausgenommen Spielercharaktere und Bosse) unter 5% fällt, während die Kreaturen davon betroffen sind, erstarren sie zu Kristall, sterben und belegen einen Gegner in der Nähe mit 'Kristallkrankheit'. Dies kann bis zu 3-mal auftreten.", ["unresolvedValues"] = true }
