entries[432768] = { ["name"] = "Feengestalt", ["text"] = "Sofort 16 sek. Abklingzeit\n- Stärkungseffekt für Zaubernden\n- Hebt Kontrollverlusteffekte auf\n- Mobilität\n\n16 Sek. Abklingzeit\nVerwandelt in eine Feenkreatur und gewährt für kurze Zeit erhöhte Bewegungsgeschwindigkeit und Immunität gegen Schwächungseffekte.\n\nWährend der Verwandlung kann nicht angegriffen werden." }
