entries[432770] = { ["name"] = "Feengestalt", ["text"] = "Sofort 12 sek. Abklingzeit\n- Stärkungseffekt für Zaubernden\n- Hebt Kontrollverlusteffekte auf\n- Mobilität\n\n12 Sek. Abklingzeit\nVerwandelt in eine Feenkreatur und gewährt für kurze Zeit erhöhte Bewegungsgeschwindigkeit und Immunität gegen Schwächungseffekte.\n\nWährend der Verwandlung kann nicht angegriffen werden." }
entries[432772] = { ["name"] = "Chikokon", ["text"] = "40 Meter Reichweite\nSofort\nIhr erhaltet einen Energieschub, der Euren nächsten Zauber verstärkt.\n\nEinhüllender Nebel : Heilt sofort um (312% der Zaubermacht) Gesundheit und ist ein Spontanzauber.\nErneuernder Nebel : Dauer um 10 Sek. erhöht.\nBeleben : Keine Manakosten.\nTritt der aufgehenden Sonne : Abklingzeit um 9 Sek. verringert.\nSchadensumleitung : Wandelt 25% zusätzliche Heilung in Schaden um und erschafft einen Chikokon, der [Gesamtgesundheit * 16 / 100 * (1 + Vielseitigkeit)] Schaden absorbiert. [ Donnernder Fokustee : Knisternder Jadeblitz : Rückstoßeffekt wird sofort angewendet.\nRollen : Erstattet eine Aufladung zurück und heilt Euch um (240% der Angriffskraft) Gesundheit ]" }
entries[432774] = { ["name"] = "Teufelskreuzschlag", ["text"] = "8 Meter Reichweite\nWirken in 1.5 sek.\nSchlägt das Ziel mit teufelserfüllten Klingen und verursacht 10 Feuerschaden." }
entries[432775] = { ["name"] = "Gefrorene Quelle", ["text"] = "100 Meter Reichweite\nSofort 2 min Abklingzeit\nVerleiht Euren Fähigkeiten die Macht der Kugel und gewährt 50 Aufladungen von 'Gefrorene Quelle'. Wenn Ihr Schaden verursacht, wird eine Aufladung verbraucht, die 23 zusätzlichen Frostschaden verursacht sowie Gegner mit 'Quellfrost' belegt, um die Bewegungsgeschwindigkeit von Gegnern um 2% pro Stapel zu verringern.\n\nWenn 'Gefrorene Quelle' vollständig verbraucht wurde, erleiden alle Ziele, die mit 'Quellfrost' belegt sind, 76 Frostschaden pro Stapel, aufgeteilt auf alle Ziele in der Nähe." }
entries[432777] = { ["name"] = "Foliant der instabilen Macht", ["text"] = "Ca. 1.5 Procs pro Minute\nEure schädlichen Zauber haben eine Chance, ein bis drei arkane Illusionen von Euch zu erzeugen. Die arkanen Illusionen kanalisieren 3 Sek. lang, bevor sie 'Arkanbeschuss' auf den Standort Eures Ziels entfesseln und allen Gegnern in diesem Bereich bis zu ( 1343 * 1.1) Arkanschaden zufügen." }
entries[432778] = { ["name"] = "Arkane Intelligenz", ["text"] = "40 Meter Reichweite\nSofort\nErfüllt das Ziel mit Brillanz, die seine Intelligenz 1 Stunde lang um 5% erhöht.\n\nWenn sich das Ziel in Eurer Gruppe oder Eurem Schlachtzug befindet, werden alle Mitglieder den Effekt erhalten." }
entries[432779] = { ["name"] = "Flamme" }
entries[432780] = { ["name"] = "Überreste plündern" }
entries[432781] = { ["name"] = "Umarmung der Leere", ["text"] = "Unbegrenzte Reichweite\nWirken in 2 sek.\nErschafft eine Hülle aus Leerenenergie, die Schaden in Höhe von 30% der maximalen Gesundheit absorbiert und den eigenen Schaden um 20% erhöht. Bei Ablauf wird der Zaubernde betäubt und erleidet 40% Schaden. Die Leere wird aus dem Körper geschleudert und fügt Spielercharakteren innerhalb der Überreste 7273348 Schattenschaden zu." }
entries[432783] = { ["name"] = "Stahlfalle", ["text"] = "Sofort\n- Kurze Reichweite\n- Bewegungsunfähigkeit durch Fallen\n- Lange Dauer\n\n16 Sek. Abklingzeit\nWirft ein Bündel Stahlfallen direkt vor den Zaubernden. Die Fallen fügen Gegnern, die sie auslösen, Schaden zu und machen diese bewegungsunfähig." }
