entries[432786] = { ["name"] = "Stahlfalle", ["text"] = "Sofort\n- Kurze Reichweite\n- Bewegungsunfähigkeit durch Fallen\n- Lange Dauer\n\n14 Sek. Abklingzeit\nWirft ein Bündel Stahlfallen direkt vor den Zaubernden. Die Fallen fügen Gegnern, die sie auslösen, Schaden zu und machen diese bewegungsunfähig." }
