entries[432789] = { ["name"] = "Teufelskrallen", ["text"] = "8 Meter Reichweite\nWirken in 1.5 sek. 1.5 sek. Abklingzeit\nSironas schlägt mit ihren Krallen zu, fügt ihrem Primärziel und bis zu 3 zusätzlichen Zielen in der Nähe 8 Feuerschaden zu." }
