entries[432794] = { ["name"] = "Dämonische Kunst: Mutter des Chaos", ["text"] = "Sofort\nEuer nächster ausgegebener Seelensplitter beschwört eine Mutter des Chaos, die einen vernichtenden Angriff entfesselt.\nModifies Cast Time 0%:\nChaosblitz , Hand von Gul'dan" }
