entries[432804] = { ["name"] = "Vorwarnung", ["text"] = "40 Meter Reichweite\nDie Abklingzeit von 'Heilige Bewaffnung' ist um 20% verringert." }
entries[432805] = { ["name"] = "Leerenrückwirkung", ["text"] = "Sofort\nErschafft eine Hülle aus Leerenenergie, die Schaden in Höhe von 30% der maximalen Gesundheit absorbiert und den eigenen Schaden um 20% erhöht. Bei Ablauf wird der Zaubernde betäubt und erleidet 40% Schaden. Die Leere wird aus dem Körper geschleudert und fügt Spielercharakteren innerhalb der Überreste 7273348 Schattenschaden zu." }
entries[432807] = { ["name"] = "Vernichtung", ["text"] = "100 Meter Reichweite\nWirken in 3.5 sek. 1.5 sek. Abklingzeit\nSironas schleudert sich in die Luft und schmettert herab, um allen Gegnern im Umkreis von 10 Metern 15 Feuerschaden zuzufügen.\n\nMehrere Teufelsblitze schlagen in der Nähe ein und fügen allen Gegnern innerhalb von 3 Metern um einen Einschlag 10 Feuerschaden zu." }
