entries[432877] = { ["name"] = "Algarischen Fläschchenkessel vorbereiten", ["text"] = "5 Meter Reichweite\nWirken in 1 sek.\nPlatziert einen Kessel, der Gruppen- und Schlachtzugsmitgliedern erlaubt, Fläschchen ihrer Wahl herauszunehmen, basierend auf den in Eurer Kriegsmeute bekannten Rezepten. Nur Alchemisten mit dem Kesselrezept tragen dazu bei.\n\nDer Kessel bleibt 5 Min. lang bestehen und hat 40 Aufladungen. Ihr erhaltet den kristallgeschmiedeten Kessel zurück, nachdem er benutzt wurde." }
