entries[432965] = { ["name"] = "Entblößen", ["text"] = "100 Meter Reichweite\nWirken in 1 sek.\nSikran schlägt auf sein Ziel ein, fügt ihm 5756315 körperlichen Schaden zu und legt eine Schwäche offen, die den erlittenen körperlichen Schaden 6 Sek. lang um 200% erhöht." }
