entries[432982] = { ["name"] = "Abstoßendes Spucken", ["text"] = "20 Meter Reichweite\nWirken in 2 sek.\nDer Zaubernde spuckt eine widerwärtige Mischung aus Netzflüssigkeit, Gift und Schmutz auf einen zufälligen Spielercharakter, die diesem alle 1 Sek. 0 Naturschaden zufügt und sein Tempo sowie seine Bewegungsgeschwindigkeit um 3% verringert. Hält 10 Sek. lang an. Dieser Effekt ist stapelbar." }
