entries[432990] = { ["name"] = "Unerbittliches Streitross", ["text"] = "'Göttliches Ross' hält 2 Sek. länger an und erhöht Eure Bewegungsgeschwindigkeit für die ersten 3 Sek. um zusätzlich 30%." }
entries[432992] = { ["name"] = "Band der Gemeinschaft", ["text"] = "Ihr erleidet 20% weniger Schaden durch 'Segen der Aufopferung'. Jedes Mal, wenn das Ziel des Zaubers Schaden erleidet, gewinnt Ihr 4% Bewegungsgeschwindigkeit hinzu, bis maximal 40%." }
entries[432994] = { ["name"] = "Optimiertes Relikt", ["text"] = "Sofort\nAußerhalb eines Kampfes steigt die Bewegungsgeschwindigkeit der Gruppenmitglieder um 10%. Bei Kampfeintritt steigt das Tempo der Gruppenmitglieder 8 Sek. lang um 5%." }
entries[432995] = { ["name"] = "Unerbittlicher Schwinger", ["text"] = "Wenn Eure Gesundheit unter 75% fällt, wird für bis zu 15 Sek. die Verteidigungsmatrix aktiviert und absorbiert 50% des erlittenen Schadens, bis zu maximal 8676 Schaden. Während die Matrix aktiv ist, pulsiert der Schwinger alle 1 Sek., um allen Gegnern in der Nähe 96 Feuerschaden zuzufügen. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\n\nDies kann nur alle 1.5 Min. auftreten." }
entries[432998] = { ["name"] = "Pestilenzblitz", ["text"] = "40 Meter Reichweite\nWirken in 1 sek.\nDer Zaubernde spuckt eine Masse geronnenen Gifts auf sein aktuelles Ziel und fügt diesem 5 Naturschaden zu." }
