entries[433214] = { ["name"] = "Frostrüstung", ["text"] = "Ca. 2 Procs pro Minute\nEure Fähigkeiten haben eine Chance, eine Frostrüstung zu gewähren, die 1 Min. lang 6690 Schaden absorbiert.\n\nAngriffe gegen die Frostrüstung lassen Eisfragmente absplittern, die dem Angreifer und Gegnern in der Nähe 99 Frostschaden zufügen und ihre Bewegungsgeschwindigkeit 1 Sek. lang um 70% verringern." }
entries[433216] = { ["name"] = "Erdbrecher", ["text"] = "100 Meter Reichweite\nWirken in 2 sek.\n- Flächenschaden um Zaubernden\n- Betäubung\n- Immunität gegenüber Kontrollverlusteffekten\n\n16 Sek. Abklingzeit\nSpaltet die Erde in einem Bereich um den Zaubernden, wodurch getroffene Gegner Schaden erleiden und betäubt werden.\n\nWährend des Zauberwirkens seid Ihr immun gegenüber Kontrollverlusteffekten." }
