entries[433356] = { ["name"] = "Lauffeuer", ["text"] = "Eure Angriffe haben eine Chance, Feuerschaden zu verursachen und 'Lauffeuer' auf einen Gegner in der Nähe überspringen zu lassen, das 10 Sek. lang alle 1 Sek. Feuerschaden verursacht.\n\n'Lauffeuer' ist bis zu 3-mal stapelbar und springt auf Gegner in der Nähe über." }
entries[433358] = { ["name"] = "Meteoritensturm", ["text"] = "Eure Fähigkeiten haben eine Chance, einen Meteoritenhagel zu beschwören, der Gegnern in der Nähe Feuerschaden zufügt und sie für 3 Sek. betäubt." }
