entries[433380] = { ["name"] = "Heiliger Schild", ["text"] = "40 Meter Reichweite\nWirken in 1 sek. 14 sek. Abklingzeit\n- Projektil\n- Erneut aktivierbar\n- Kurze Reichweite\n\n14 Sek. Abklingzeit\nSchleudert einen gesegneten Schild nach vorn, der Gegnern in seinem Weg Schaden zufügt, bevor er zu Euch zurückkehrt.\n\nErneut einsetzen, um eine heilige Explosion im Gebiet um den Schild herum auszulösen." }
