entries[433522] = { ["name"] = "Kristallkrankheit", ["text"] = "60 Meter Reichweite\nSofort\nEure schädlichen Zauber und Fähigkeiten haben eine geringe Chance, die tragischen Arkanmächte anzurufen, damit sie Euer Ziel mit 'Kristallkrankheit' belegen. Betroffene Ziele erleiden [Quellwert] Arkanschaden im Verlauf von 10 Sek., der mit jeder Sekunde ansteigt.\n\nWenn die Gesundheit von Kreaturen (ausgenommen Spielercharaktere und Bosse) unter 5% fällt, während die Kreaturen davon betroffen sind, erstarren sie zu Kristall, sterben und belegen einen Gegner in der Nähe mit 'Kristallkrankheit'. Dies kann bis zu 3-mal auftreten.", ["unresolvedValues"] = true }
