entries[433618] = { ["name"] = "Wem die Stunde schlägt", ["text"] = "Sofort\n'Göttlicher Glockenschlag' lässt 3 Einsätze von 'Richturteil' bis zu 100% mehr Schaden verursachen, wenn nur 1 Ziel getroffen wird. Dieser Wert verringert sich um 20% pro zusätzlichem getroffenem Ziel." }
entries[433620] = { ["name"] = "Läuternde Salbe", ["text"] = "Sofort\nBrann verschießt Beruhigungspfeile auf ermächtigte Gegner, die 1 Wut-- und 1 Magieeffekte aufheben." }
entries[433621] = { ["name"] = "Dreißig Meter Seil", ["text"] = "Sofort\nBrann wirft Spielercharakteren sein Seil zu, um sie von Betäubungs-, Bewegungsunfähigkeits- und Verlangsamungseffekten zu befreien. Diese werden dadurch 4 Sek. lang immun gegenüber allen derartigen Effekten." }
entries[433622] = { ["name"] = "Notvorräte", ["text"] = "100 Meter Reichweite\nSofort\nWenn die Gesundheit eines Spielercharakters unter 30% fällt, heilt Brann ihn sofort um 25% seiner maximalen Gesundheit. Kann nur alle 3 Min. auftreten." }
entries[433627] = { ["name"] = "Treue Peitsche", ["text"] = "Sofort\nBrann schlägt den Gegner mit seiner Peitsche, unterbricht das Wirken von Zaubern und verhindert 3 Sek. lang, dass Zauber dieser Art gewirkt werden können." }
entries[433629] = { ["name"] = "Frostfalle", ["text"] = "Sofort\nWenn 3 oder mehr Gegner einen Verbündeten angreifen, schleudert Brann eine Frostfalle auf sie, die ihre Bewegungsgeschwindigkeit um 50% verringert und sie gelegentlich 3 Sek. lang festhält. Die Falle bleibt 15 Sek. lang bestehen." }
entries[433642] = { ["name"] = "Maulwurfmaschine rufen", ["text"] = "45 Meter Reichweite\nSofort 15 sek. Abklingzeit\nRuft eine Maulwurfmaschine, um alle Einheiten in einem Bereich zurückzustoßen und ihnen Schaden zuzufügen.\n\nDie Maulwurfmaschine befreit außerdem verlorene Schätze in verdächtig aussehenden Kohlenhaufen." }
